changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.card-accepted-by-user.enabled', 'true', 'BOOLEAN', 'Notify the assigning supervisor when the attached user accepts a Card (NEW -> ACCEPTED_BY_USER).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.card-accepted-by-user.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.card-rejected-by-user.enabled', 'true', 'BOOLEAN', 'Notify the assigning supervisor when the attached user rejects a Card (-> REJECTED_BY_USER).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.card-rejected-by-user.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.card-completed.enabled', 'true', 'BOOLEAN', 'Notify the assigning supervisor when the attached user marks a Card completed and ready for review (-> COMPLETED).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.card-completed.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.card-approved.enabled', 'true', 'BOOLEAN', 'Notify the attached user(s) when the supervisor approves a Card (COMPLETED -> APPROVED).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.card-approved.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.card-rejected.enabled', 'true', 'BOOLEAN', 'Notify the attached user(s) when the supervisor sends a Card back for rework (COMPLETED -> REJECTED).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.card-rejected.enabled');
